<div class="container"><div class="page-heading"><span class="section-kicker">Pengajuan #<?= (int) $application['id'] ?></span><h1><?= e($application['type_name']) ?></h1><p>Diajukan <?= e(date('d F Y, H:i', strtotime($application['created_at']))) ?></p></div><div class="row g-4"><div class="col-lg-7"><section class="data-panel"><div class="d-flex justify-content-between gap-3 flex-wrap"><h2 class="h5">Status layanan</h2><span class="status-pill pending"><?= e(status_label($application['status'])) ?></span></div><div class="timeline mt-4"><?php foreach ($history as $item): ?><div class="timeline-item"><strong><?= e(status_label($item['new_status'])) ?></strong><?php if ($item['note']): ?><small><?= e($item['note']) ?></small><?php endif; ?><small><?= e(date('d/m/Y H:i', strtotime($item['created_at']))) ?></small></div><?php endforeach; ?></div></section></div><div class="col-lg-5"><section class="data-panel"><h2 class="h6">Keperluan</h2><p class="small text-secondary"><?= e((json_decode($application['payload'], true) ?: [])['keperluan'] ?? '') ?></p><p class="small text-secondary mb-0">Untuk verifikasi identitas, tunggu instruksi petugas dan bawa dokumen asli ke kantor desa.</p><?php if ($letter && in_array($application['status'], ['issued', 'ready_pickup', 'picked_up'], true)): ?><hr><a class="btn btn-outline-success btn-sm" href="/surat/<?= (int) $application['id'] ?>/cetak" target="_blank" rel="noopener">Pratinjau / cetak surat</a><?php endif; ?></section></div></div><a class="small d-inline-block mt-4" href="/dashboard">Kembali ke dashboard</a></div>